SELECT v.id,v.user_id,v.times_quizzed,v.last_quizzed_at::text,v.last_correct_at::text,v.created_at::text,v.updated_at::text,jsonb_build_object('legacy_dictionary_id',e.id,'source',e.source,'is_curated',e.is_curated,'save_count',e.save_count,'created_at',e.created_at,'updated_at',e.updated_at) AS metadata,
jsonb_build_object('word',e.word,'phonetic',COALESCE(e.phonetic,''),'phonetics',jsonb_build_array(jsonb_build_object('text',COALESCE(e.phonetic,''),'audio',COALESCE(e.audio_url,''))),
'meanings',COALESCE((SELECT jsonb_agg(jsonb_build_object('partOfSpeech',COALESCE(m.part_of_speech,''),'synonyms',COALESCE((SELECT jsonb_agg(term ORDER BY position,id) FROM dictionary_synonyms WHERE dictionary_entry_id=e.id AND dictionary_meaning_id IS NULL),'[]'::jsonb),'antonyms',COALESCE((SELECT jsonb_agg(term ORDER BY position,id) FROM dictionary_antonyms WHERE dictionary_entry_id=e.id AND dictionary_meaning_id IS NULL),'[]'::jsonb),
'definitions',jsonb_build_array(jsonb_build_object('definition',m.definition,'example','','examples',COALESCE((SELECT jsonb_agg(example ORDER BY position,id) FROM dictionary_examples WHERE dictionary_meaning_id=m.id),'[]'::jsonb),'synonyms',COALESCE((SELECT jsonb_agg(term ORDER BY position,id) FROM dictionary_synonyms WHERE dictionary_meaning_id=m.id),'[]'::jsonb),'antonyms',COALESCE((SELECT jsonb_agg(term ORDER BY position,id) FROM dictionary_antonyms WHERE dictionary_meaning_id=m.id),'[]'::jsonb)))) ORDER BY m.position,m.id) FROM dictionary_meanings m WHERE m.dictionary_entry_id=e.id),'[]'::jsonb)) AS entry
FROM vocabularies v LEFT JOIN dictionary_entries e ON e.id=v.dictionary_entry_id WHERE v.id>$1 ORDER BY v.id LIMIT 100
